#include <climits>
#include <memory>
#include <optional>
#include <stdexcept>
#include <vector>

class OrderedSet
{
public:
    bool insert(int key) { return insert(root_, key); }
    bool erase(int key) { return erase(root_, key); }

    bool contains(int key) const
    {
        const Node* n = root_.get();
        while (n && n->key != key) n = key < n->key ? n->left.get() : n->right.get();
        return n != nullptr;
    }

    std::size_t size() const { return sizeOf(root_); }

    std::optional<int> min() const
    {
        const Node* n = root_.get();
        if (!n) return std::nullopt;
        while (n->left) n = n->left.get();
        return n->key;
    }

    std::optional<int> max() const
    {
        const Node* n = root_.get();
        if (!n) return std::nullopt;
        while (n->right) n = n->right.get();
        return n->key;
    }

    std::optional<int> floor(int x) const
    {
        std::optional<int> best;
        for (const Node* n = root_.get(); n;)
        {
            if (n->key == x) return x;
            if (n->key < x) { best = n->key; n = n->right.get(); }
            else n = n->left.get();
        }
        return best;
    }

    std::optional<int> ceiling(int x) const
    {
        std::optional<int> best;
        for (const Node* n = root_.get(); n;)
        {
            if (n->key == x) return x;
            if (n->key > x) { best = n->key; n = n->left.get(); }
            else n = n->right.get();
        }
        return best;
    }

    std::size_t rank(int x) const
    {
        std::size_t r = 0;
        for (const Node* n = root_.get(); n;)
        {
            if (x <= n->key) n = n->left.get();
            else
            {
                r += sizeOf(n->left) + 1;
                n = n->right.get();
            }
        }
        return r;
    }

    int select(std::size_t k) const
    {
        if (k >= size()) throw std::out_of_range("select");
        const Node* n = root_.get();
        while (true)
        {
            std::size_t left = sizeOf(n->left);
            if (k < left) n = n->left.get();
            else if (k == left) return n->key;
            else
            {
                k -= left + 1;
                n = n->right.get();
            }
        }
    }

    std::size_t countBetween(int lo, int hi) const
    {
        if (lo > hi) return 0;
        std::size_t upTo = hi == INT_MAX ? size() : rank(hi + 1);
        return upTo - rank(lo);
    }

    std::vector<int> toVector() const
    {
        std::vector<int> out;
        collect(root_.get(), out);
        return out;
    }

private:
    struct Node
    {
        int key;
        std::size_t size = 1;
        std::unique_ptr<Node> left, right;
    };

    static std::size_t sizeOf(const std::unique_ptr<Node>& n) { return n ? n->size : 0; }
    static void fix(Node& n) { n.size = 1 + sizeOf(n.left) + sizeOf(n.right); }

    static bool insert(std::unique_ptr<Node>& link, int key)
    {
        if (!link)
        {
            link = std::make_unique<Node>();
            link->key = key;
            return true;
        }
        if (key == link->key) return false;
        bool added = insert(key < link->key ? link->left : link->right, key);
        if (added) fix(*link);
        return added;
    }

    static bool erase(std::unique_ptr<Node>& link, int key)
    {
        if (!link) return false;
        bool removed;
        if (key < link->key) removed = erase(link->left, key);
        else if (key > link->key) removed = erase(link->right, key);
        else
        {
            if (!link->left) { link = std::move(link->right); return true; }
            if (!link->right) { link = std::move(link->left); return true; }
            const Node* successor = link->right.get();
            while (successor->left) successor = successor->left.get();
            link->key = successor->key;
            removed = erase(link->right, successor->key);
        }
        if (removed) fix(*link);
        return removed;
    }

    static void collect(const Node* n, std::vector<int>& out)
    {
        if (!n) return;
        collect(n->left.get(), out);
        out.push_back(n->key);
        collect(n->right.get(), out);
    }

    std::unique_ptr<Node> root_;
};

unitTests:
#include <algorithm>
#include <climits>
#include <random>
#include <set>

TEST("insert, contains, erase") {
    OrderedSet s;
    for (int k : { 50, 30, 70, 20, 40, 60, 80, 35, 45 }) CHECK(s.insert(k));
    CHECK(!s.insert(40));
    CHECK_EQ(s.size(), std::size_t{ 9 });
    CHECK(s.contains(35));
    CHECK(!s.contains(36));
    CHECK(s.erase(20));                       // a leaf
    CHECK(s.erase(70));                       // two children
    CHECK(s.erase(30));                       // two children
    CHECK(!s.erase(30));
    CHECK_EQ(s.toVector(), (std::vector<int>{ 35, 40, 45, 50, 60, 80 }));
    CHECK_EQ(s.size(), std::size_t{ 6 });
}
TEST("min, max, floor and ceiling") {
    OrderedSet s;
    CHECK(!s.min().has_value());
    CHECK(!s.floor(3).has_value());
    for (int k : { 50, 30, 70, 20, 40, 60, 80 }) s.insert(k);
    CHECK_EQ(*s.min(), 20);
    CHECK_EQ(*s.max(), 80);
    CHECK_EQ(*s.floor(44), 40);
    CHECK_EQ(*s.floor(50), 50);
    CHECK(!s.floor(19).has_value());
    CHECK_EQ(*s.ceiling(44), 50);
    CHECK_EQ(*s.ceiling(-100), 20);
    CHECK(!s.ceiling(81).has_value());
}
TEST("rank, select and ranges") {
    OrderedSet s;
    for (int k : { 50, 30, 70, 20, 40, 60, 80 }) s.insert(k);
    CHECK_EQ(s.rank(20), std::size_t{ 0 });
    CHECK_EQ(s.rank(45), std::size_t{ 3 });
    CHECK_EQ(s.rank(1000), std::size_t{ 7 });
    CHECK_EQ(s.select(0), 20);
    CHECK_EQ(s.select(3), 50);
    CHECK_EQ(s.select(6), 80);
    CHECK_THROWS(s.select(7));
    CHECK_EQ(s.countBetween(30, 60), std::size_t{ 4 });
    CHECK_EQ(s.countBetween(31, 39), std::size_t{ 0 });
    CHECK_EQ(s.countBetween(60, 30), std::size_t{ 0 });
    s.insert(INT_MAX);
    s.insert(INT_MIN);
    CHECK_EQ(s.countBetween(INT_MIN, INT_MAX), std::size_t{ 9 });
    s.erase(50);
    CHECK_EQ(s.select(3), 40);
    CHECK_EQ(s.select(4), 60);
}
TEST("matches std::set over 20,000 random operations") {
    OrderedSet s;
    std::set<int> ref;
    std::mt19937 rng(99);
    bool same = true;
    for (int step = 0; step < 20000; ++step)
    {
        int k = static_cast<int>(rng() % 5000);
        if (rng() % 3) same = same && s.insert(k) == ref.insert(k).second;
        else same = same && s.erase(k) == (ref.erase(k) == 1);
    }
    CHECK(same);
    CHECK_EQ(s.size(), ref.size());
    CHECK(s.toVector() == std::vector<int>(ref.begin(), ref.end()));
    bool ranks = true;
    for (int x = -1; x <= 5000; x += 7)
        ranks = ranks && s.rank(x) == static_cast<std::size_t>(std::distance(ref.begin(), ref.lower_bound(x)));
    CHECK(ranks);
    std::size_t k = ref.size() / 2;
    CHECK_EQ(s.select(k), *std::next(ref.begin(), static_cast<long>(k)));
}

